",#(lf)    'NAO' AS ""Ind Ciclo Rateio"",#(lf)    '' AS ""Conta Contrapartida"",#(lf)    '' AS ""Tipo Conta Contrapartida"",#(lf)    '' AS ""Descricao Contrapartida"",*/#(lf)    1 AS ""Tipo Lancamento""#(lf)#(lf)FROM trusted.partner_source_sap_coej a#(lf)INNER JOIN trusted.partner_source_sap_csks b ON a.objnr = b.objnr#(lf)CROSS JOIN LATERAL (#(lf)    SELECT#(lf)        unnest(ARRAY['wtg001','wtg002','wtg003','wtg004','wtg005','wtg006','wtg007','wtg008','wtg009','wtg010','wtg011','wtg012']) AS coluna,#(lf)        unnest(ARRAY[a.wtg001,a.wtg002,a.wtg003,a.wtg004,a.wtg005,a.wtg006,a.wtg007,a.wtg008,a.wtg009,a.wtg010,a.wtg011,a.wtg012]) AS valor#(lf)) AS wtg#(lf)WHERE a.gjahr::int BETWEEN (EXTRACT(YEAR FROM CURRENT_DATE) - 1)::int#(lf)                       AND (EXTRACT(YEAR FROM CURRENT_DATE) )::int", null, [EnableFolding=true])//,
